$lan584_data$::JSONB);

DO $$
DECLARE
    mismatch RECORD;
BEGIN
    IF (SELECT COUNT(*) FROM lan584_updates) <> 275
       OR (SELECT COUNT(DISTINCT expression_id) FROM lan584_updates) <> 189
    THEN
        RAISE EXCEPTION 'LAN-584 manifest count mismatch';
    END IF;

    SELECT mapping.expression_id, mapping.example_number INTO mismatch
    FROM lan584_updates mapping
    LEFT JOIN writing_expression expression ON expression.id = mapping.expression_id
    WHERE expression.id IS NULL
       OR expression.expression_source IS DISTINCT FROM mapping.expression_source
       OR expression.target_locale IS DISTINCT FROM 'EN'
       OR expression.base_locale IS DISTINCT FROM 'KR'
       OR CASE WHEN jsonb_typeof(expression.practice_examples_payload) = 'array'
               THEN jsonb_array_length(expression.practice_examples_payload) ELSE 0 END <> 4
       OR EXISTS (
           SELECT 1 FROM jsonb_each(mapping.expected_example) field
           WHERE expression.practice_examples_payload -> (mapping.example_number - 1) -> field.key
                 IS DISTINCT FROM field.value
       )
    ORDER BY mapping.expression_id, mapping.example_number
    LIMIT 1;
    IF FOUND THEN
        RAISE EXCEPTION 'LAN-584 source precondition failed: expression %, example %',
            mismatch.expression_id, mismatch.example_number;
    END IF;

    IF EXISTS (
        SELECT 1 FROM lan584_updates mapping
        WHERE jsonb_typeof(words) IS DISTINCT FROM 'array'
           OR jsonb_typeof(choices) IS DISTINCT FROM 'array'
           OR jsonb_array_length(words) < 3
           OR jsonb_array_length(choices) - jsonb_array_length(words)
                <> jsonb_array_length(expected_example -> 'sentenceWordChoices')
                   - jsonb_array_length(expected_example -> 'sentenceWords')
           OR replace(replace(array_to_string(
                    ARRAY(SELECT jsonb_array_elements_text(words)), ' '), '-', ' '), '''', '')
                IS DISTINCT FROM replace(replace(array_to_string(
                    ARRAY(SELECT jsonb_array_elements_text(expected_example -> 'sentenceWords')),
                    ' '), '-', ' '), '''', '')
           OR EXISTS (
               SELECT jsonb_array_elements(words)
               EXCEPT ALL
               SELECT jsonb_array_elements(choices)
           )
           OR EXISTS (
               SELECT 1 FROM jsonb_array_elements(words || choices) token
               WHERE jsonb_typeof(token) <> 'string' OR btrim(token #>> '{}') = ''
           )
    ) THEN
        RAISE EXCEPTION 'LAN-584 invalid chip manifest';
    END IF;
END $$;

CREATE TEMP TABLE lan584_originals ON COMMIT DROP AS
SELECT expression.id, to_jsonb(expression) AS original_record,
       expression.practice_examples_payload AS payload
FROM writing_expression expression
WHERE expression.id IN (SELECT expression_id FROM lan584_updates);

CREATE TEMP TABLE lan584_patched ON COMMIT DROP AS
SELECT original.id,
       jsonb_agg(
           CASE WHEN mapping.expression_id IS NULL THEN example.value
                ELSE jsonb_set(jsonb_set(example.value, '{sentenceWords}', mapping.words, false),
                               '{sentenceWordChoices}', mapping.choices, false)
           END ORDER BY example.ordinality
       ) AS payload
FROM lan584_originals original
CROSS JOIN LATERAL jsonb_array_elements(original.payload)
    WITH ORDINALITY AS example(value, ordinality)
LEFT JOIN lan584_updates mapping
  ON mapping.expression_id = original.id AND mapping.example_number = example.ordinality
GROUP BY original.id;

UPDATE writing_expression expression
SET practice_examples_payload = patched.payload
FROM lan584_patched patched
WHERE expression.id = patched.id;

DO $$
BEGIN
    IF (SELECT COUNT(*) FROM lan584_originals) <> 189
       OR EXISTS (
           SELECT 1 FROM lan584_originals original
           JOIN lan584_patched patched ON patched.id = original.id
           LEFT JOIN writing_expression expression ON expression.id = original.id
           WHERE expression.id IS NULL
              OR to_jsonb(expression) IS DISTINCT FROM jsonb_set(
                  original.original_record, '{practice_examples_payload}', patched.payload, false)
       )
    THEN
        RAISE EXCEPTION 'LAN-584 postcondition failed: chip or unrelated field changed';
    END IF;
END $$;
